content.arguments:
{"command":"cmd /c "dir /s /b D:\tool-probe.json D:\干活\tool-probe.json 2>nul"
Write-Output "--- scan D:\干活 (depth-limited, 8 levels) ---"
$found = @()
$stack = [System.Collections.Generic.List[string]]::new()
$stack.Add('D:\干活')
$n=0
while ($stack.Count -gt 0 -and $n -lt 40000) {
  $d = $stack[$stack.Count-1]; $stack.RemoveAt($stack.Count-1)
  try { $items = [System.IO.Directory]::EnumerateFileSystemEntries($d) } catch { continue }
  foreach ($i in $items) {
    $n++
    if ([System.IO.Path]::GetFileName($i) -eq 'tool-probe.json') { $found += $i }
    if ([System.IO.Directory]::Exists($i) -and ([System.IO.Path]::GetFileName($i) -notmatch '^(node_modules|\.git|\.next|dist|build)$')) {
      $depth = ($i -replace '^D:\\干活\\?','').Split('\').Count
      if ($depth -le 8) { $stack.Add($i) }
    }
  }
}
Write-Output "scanned $n entries"
if ($found.Count -eq 0) { Write-Output 'NOT FOUND' } else { $found | Select-Object -First 10 }","description":"Recursively scan workspace for tool-probe.json"}

